('av_hwsPP3h3y4hQyYjZb-csipEPd1YOYpdC6-KB9i6zDKuW8kCLZcqm2bYe7QepL0zz36FmmaR2EF-xw4M','阴阳路惊魂',2026,'movie','中国大陆',NULL,'["惊悚","悬疑","恐怖"]','["崔永炫","单明凯","傅天","何雨宸","黄城","雷琨","李双","刘硕","刘铁柱","倪学增","王丽萍","张宸彬"]','["徐俊"]','https://gimg0.baidu.com/gimg/app=2001&n=0&g=0n&fmt=webp&src=img.baipiaozhe.com/assets/images/a2/a29c3bfcb1b9f07a0d4b84316b585ca6d991dc6f98ed424d3f3c3aa8d98fe27d.webp',NULL,'影片讲述民国年间,永夜诡镇阴森可怖,阴阳路有进无出,镇民死逃殆尽,却有访客为睹雪新娘冒死前来——她冰肌胜雪、唇红似血,不敬者必见“红如鲜血、白如骨骸”的惨状。镇中避祸规矩:供糯米血饭、燃梅花香摆锁魂阵、跨旺火盆躲进阴阳轩。 阴阳轩内更邪:于掌柜讲“尸变借魂”诡事,江大厨骨汤飘腥气;阳客有热汤暖身,阴魂有纸人侍奉,后堂朱漆宝棺虚位以待。顾梦寒携红衣新娘躲入,仍难逃劫数:催命刀破空,纸人骤燃现鬼影;雪打招魂幡似魂魄挣命,棺木晃动,三丈显道神睁眼喝问:“你可知罪?”','高清',1,1,91.92,'最近上线 预告片'),
