('av_jwN2aSXPHdp2lqSobDn0ZGn7cExbQn_iJfpukd4HGeA0VVW88b_oK4kdGo43Gkrmseig5S_3CFYPJkk','美人图',2008,'movie','韩国',NULL,'["爱情"]','["金圭丽","金南佶","金英浩","秋瓷炫"]','["田昀树"]','https://gimg0.baidu.com/gimg/app=2001&n=0&g=0n&fmt=webp&src=img.baipiaozhe.com/assets/images/ce/ce3b742bf6c3a3fc5160017a21a6cba3553c392dc574b175a2af11e73bc95a90.webp',NULL,'《美人图》说的是朝鲜史上有名的女扮男装天才画家申润福的故事。 申润福(金敏善 饰)的父亲将家族的兴旺寄予这个可怜的女孩,隐藏其女儿身,改以男儿身打扮亮相,跟随着当地有的画家金洪道(金英浩 饰)学习,苦学画技,以卖画给地主们维持生计。性格粗野的姜武(金南吉 饰)是市井青铜镜商人,一次偶然中发现了申润福的女人身份,与她相爱,并使润福认识到身为女人如命运般的爱情。但申润福的老师金洪道与徒弟之间也有一种奇妙的感情,他不容许润福背叛自己,千方百计阻止润福和姜武。而名妓雪花(秋瓷炫 饰)则深爱着金洪道。四个人将会走向何处?申润福和姜武能守护住自己的爱情吗?申润福的女子身份会被揭露吗?最终她是否能改变自己的一生,成为朝鲜知名画家?','高清',1,1,81.4,'最近上线 正片'),
('av_jxLZLDLhF1bbAEkauUX8YstJ_JyyM6Gev4SDtbQpTnmlTpvLWhcrOrJpZh1SW08knWlLuUMGCM8T_cs','小欢喜',2019,'series','中国大陆','国语','["国产剧","剧情","家庭","连续剧","都市","连续","内地","国产","电视剧","大陆"]','["海清","黄磊","陶虹","王砚辉","郭子凡","李庚希","任重","沙溢","王栎鑫","吴施乐","徐梵溪","咏梅"]','["汪俊"]','https://gimg0.baidu.com/gimg/app=2001&n=0&g=0n&fmt=webp&src=img.baipiaozhe.com/assets/images/37/37c82601bcdc4b6d108b96ccc49ae05f3d3e17da3a690e7bf935f49c1ab8f5a8.webp','https://gimg0.baidu.com/gimg/app=2001&n=0&g=0n&fmt=webp&src=img.baipiaozhe.com/assets/images/a3/a3bb672e48b7fd59ce00161ecd4adb9b618e79bdbadf1aa74830429809ad6f24.webp','北京市,三个备战高考的家庭不仅面对着升学压力,更面对着亲子关系难题。恨铁不成钢的妈妈童文洁(海清 饰)和学渣儿子方一凡(周奇 饰)之间因为成绩矛盾重重,爸爸方圆(黄磊 饰)不得不左右调停;拒绝前夫乔卫东(沙溢 饰)入侵母女生活的单亲妈妈宋倩(陶虹 饰),对女儿乔英子(李庚希 饰)的生活展开了全包围式关切,误解和矛盾不知不觉悄然爆发;空降父亲季胜利(王砚辉 饰)和妈妈刘静(咏梅 饰)的突然关怀,让从小养在舅舅刘铮(任重 饰)身边的季杨杨(郭子凡 饰)无所适从,父子之间小心翼翼的相处并没有为这段关系换来和平。 人到中年的家长和刚刚迎来成年的孩子,在高三这场重要的试炼中,度过生活设置的重重难题,在爱与理解中学会成长,迎来属于自己的“小欢喜”。','全49集',49,49,127.21,'2026-11-04T06:36:26.658Z'),
